package com.symphony.bdk.workflow.engine;

import org.junit.jupiter.api.Test;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatCode;

/**
 * Test class specifically targeting the static initialization (<clinit>) of the Gateway enum.
 * The <clinit> method is automatically generated by the compiler to initialize enum constants.
 * Lines 97-100 in WorkflowDirectedGraph.java define the Gateway enum with three constants:
 * EXCLUSIVE, EVENT_BASED, and PARALLEL.
 */
class WorkflowDirectedGraphClaude_clinitTest {

  // Tests to trigger the static initialization of the Gateway enum
  // The <clinit> method is executed when the enum class is first loaded

  @Test
  void clinit_shouldInitializeExclusiveConstant() {
    // When: Accessing the EXCLUSIVE enum constant (triggers class loading and <clinit>)
    WorkflowDirectedGraph.Gateway gateway = WorkflowDirectedGraph.Gateway.EXCLUSIVE;

    // Then: The constant should be properly initialized
    assertThat(gateway).isNotNull();
    assertThat(gateway.name()).isEqualTo("EXCLUSIVE");
    assertThat(gateway.ordinal()).isEqualTo(0);
  }

  @Test
  void clinit_shouldInitializeEventBasedConstant() {
    // When: Accessing the EVENT_BASED enum constant (triggers class loading and <clinit>)
    WorkflowDirectedGraph.Gateway gateway = WorkflowDirectedGraph.Gateway.EVENT_BASED;

    // Then: The constant should be properly initialized
    assertThat(gateway).isNotNull();
    assertThat(gateway.name()).isEqualTo("EVENT_BASED");
    assertThat(gateway.ordinal()).isEqualTo(1);
  }

  @Test
  void clinit_shouldInitializeParallelConstant() {
    // When: Accessing the PARALLEL enum constant (triggers class loading and <clinit>)
    WorkflowDirectedGraph.Gateway gateway = WorkflowDirectedGraph.Gateway.PARALLEL;

    // Then: The constant should be properly initialized
    assertThat(gateway).isNotNull();
    assertThat(gateway.name()).isEqualTo("PARALLEL");
    assertThat(gateway.ordinal()).isEqualTo(2);
  }

  @Test
  void clinit_shouldInitializeAllThreeEnumConstants() {
    // When: Calling values() which requires all enum constants to be initialized
    WorkflowDirectedGraph.Gateway[] values = WorkflowDirectedGraph.Gateway.values();

    // Then: All three constants from lines 98-100 should be initialized
    assertThat(values).hasSize(3);
    assertThat(values).containsExactly(
        WorkflowDirectedGraph.Gateway.EXCLUSIVE,
        WorkflowDirectedGraph.Gateway.EVENT_BASED,
        WorkflowDirectedGraph.Gateway.PARALLEL
    );
  }

  @Test
  void clinit_shouldAllowValueOfToFindInitializedConstants() {
    // When: Using valueOf to look up enum constants by name
    // This ensures the <clinit> method has properly registered all enum instances

    // Then: All constants should be findable
    assertThat(WorkflowDirectedGraph.Gateway.valueOf("EXCLUSIVE"))
        .isEqualTo(WorkflowDirectedGraph.Gateway.EXCLUSIVE);
    assertThat(WorkflowDirectedGraph.Gateway.valueOf("EVENT_BASED"))
        .isEqualTo(WorkflowDirectedGraph.Gateway.EVENT_BASED);
    assertThat(WorkflowDirectedGraph.Gateway.valueOf("PARALLEL"))
        .isEqualTo(WorkflowDirectedGraph.Gateway.PARALLEL);
  }

  @Test
  void clinit_enumConstantsShouldBeUnique() {
    // When: Getting all enum constants
    WorkflowDirectedGraph.Gateway exclusive = WorkflowDirectedGraph.Gateway.EXCLUSIVE;
    WorkflowDirectedGraph.Gateway eventBased = WorkflowDirectedGraph.Gateway.EVENT_BASED;
    WorkflowDirectedGraph.Gateway parallel = WorkflowDirectedGraph.Gateway.PARALLEL;

    // Then: Each constant should be a unique instance
    assertThat(exclusive).isNotSameAs(eventBased);
    assertThat(exclusive).isNotSameAs(parallel);
    assertThat(eventBased).isNotSameAs(parallel);
  }

  @Test
  void clinit_enumConstantsShouldBeSingletons() {
    // When: Accessing the same enum constant multiple times
    WorkflowDirectedGraph.Gateway exclusive1 = WorkflowDirectedGraph.Gateway.EXCLUSIVE;
    WorkflowDirectedGraph.Gateway exclusive2 = WorkflowDirectedGraph.Gateway.EXCLUSIVE;

    // Then: The same singleton instance should be returned
    assertThat(exclusive1).isSameAs(exclusive2);
  }

  @Test
  void clinit_shouldInitializeEnumInDeclarationOrder() {
    // When: Checking the ordinal values of enum constants
    // The <clinit> method initializes them in the order they're declared (lines 98-100)

    // Then: Ordinals should match declaration order
    assertThat(WorkflowDirectedGraph.Gateway.EXCLUSIVE.ordinal()).isEqualTo(0);
    assertThat(WorkflowDirectedGraph.Gateway.EVENT_BASED.ordinal()).isEqualTo(1);
    assertThat(WorkflowDirectedGraph.Gateway.PARALLEL.ordinal()).isEqualTo(2);
  }

  @Test
  void clinit_valuesShouldReturnArrayWithAllInitializedConstants() {
    // When: Calling values() to get all enum constants
    WorkflowDirectedGraph.Gateway[] values = WorkflowDirectedGraph.Gateway.values();

    // Then: The array should contain all constants initialized in <clinit>
    assertThat(values).isNotEmpty();
    assertThat(values[0]).isEqualTo(WorkflowDirectedGraph.Gateway.EXCLUSIVE);
    assertThat(values[1]).isEqualTo(WorkflowDirectedGraph.Gateway.EVENT_BASED);
    assertThat(values[2]).isEqualTo(WorkflowDirectedGraph.Gateway.PARALLEL);
  }

  @Test
  void clinit_enumConstantsShouldBeComparable() {
    // When: Comparing enum constants (which relies on proper initialization)
    WorkflowDirectedGraph.Gateway exclusive = WorkflowDirectedGraph.Gateway.EXCLUSIVE;
    WorkflowDirectedGraph.Gateway eventBased = WorkflowDirectedGraph.Gateway.EVENT_BASED;
    WorkflowDirectedGraph.Gateway parallel = WorkflowDirectedGraph.Gateway.PARALLEL;

    // Then: They should be comparable based on their ordinal values from <clinit>
    assertThat(exclusive.compareTo(eventBased)).isLessThan(0);
    assertThat(eventBased.compareTo(parallel)).isLessThan(0);
    assertThat(parallel.compareTo(exclusive)).isGreaterThan(0);
    assertThat(exclusive.compareTo(exclusive)).isEqualTo(0);
  }

  @Test
  void clinit_enumConstantsShouldBeUsableInSwitchStatements() {
    // When: Using enum constants in a switch statement (requires proper initialization)
    String result;
    switch (WorkflowDirectedGraph.Gateway.EXCLUSIVE) {
      case EXCLUSIVE:
        result = "exclusive";
        break;
      case EVENT_BASED:
        result = "event_based";
        break;
      case PARALLEL:
        result = "parallel";
        break;
      default:
        result = "unknown";
        break;
    }

    // Then: The switch should work correctly
    assertThat(result).isEqualTo("exclusive");
  }

  @Test
  void clinit_allEnumConstantsShouldBeUsableInSwitchStatements() {
    // When: Testing all enum constants in switch statements
    for (WorkflowDirectedGraph.Gateway gateway : WorkflowDirectedGraph.Gateway.values()) {
      String result;
      switch (gateway) {
        case EXCLUSIVE:
          result = "exclusive";
          break;
        case EVENT_BASED:
          result = "event_based";
          break;
        case PARALLEL:
          result = "parallel";
          break;
        default:
          result = "unknown";
          break;
      }

      // Then: Each constant should match correctly
      assertThat(result).isIn("exclusive", "event_based", "parallel");
    }
  }

  @Test
  void clinit_enumConstantsShouldHaveCorrectToString() {
    // When: Getting the string representation of enum constants
    // The default toString() uses the name initialized in <clinit>

    // Then: toString should return the correct name
    assertThat(WorkflowDirectedGraph.Gateway.EXCLUSIVE.toString()).isEqualTo("EXCLUSIVE");
    assertThat(WorkflowDirectedGraph.Gateway.EVENT_BASED.toString()).isEqualTo("EVENT_BASED");
    assertThat(WorkflowDirectedGraph.Gateway.PARALLEL.toString()).isEqualTo("PARALLEL");
  }

  @Test
  void clinit_enumConstantsShouldBeEqualToThemselves() {
    // When: Comparing enum constants to themselves
    WorkflowDirectedGraph.Gateway exclusive = WorkflowDirectedGraph.Gateway.EXCLUSIVE;
    WorkflowDirectedGraph.Gateway eventBased = WorkflowDirectedGraph.Gateway.EVENT_BASED;
    WorkflowDirectedGraph.Gateway parallel = WorkflowDirectedGraph.Gateway.PARALLEL;

    // Then: Each constant should equal itself
    assertThat(exclusive.equals(exclusive)).isTrue();
    assertThat(eventBased.equals(eventBased)).isTrue();
    assertThat(parallel.equals(parallel)).isTrue();
  }

  @Test
  void clinit_enumConstantsShouldNotBeEqualToEachOther() {
    // When: Comparing different enum constants
    WorkflowDirectedGraph.Gateway exclusive = WorkflowDirectedGraph.Gateway.EXCLUSIVE;
    WorkflowDirectedGraph.Gateway eventBased = WorkflowDirectedGraph.Gateway.EVENT_BASED;
    WorkflowDirectedGraph.Gateway parallel = WorkflowDirectedGraph.Gateway.PARALLEL;

    // Then: Different constants should not be equal
    assertThat(exclusive.equals(eventBased)).isFalse();
    assertThat(exclusive.equals(parallel)).isFalse();
    assertThat(eventBased.equals(parallel)).isFalse();
  }

  @Test
  void clinit_enumConstantsShouldHaveConsistentHashCodes() {
    // When: Getting hash codes for enum constants
    WorkflowDirectedGraph.Gateway exclusive = WorkflowDirectedGraph.Gateway.EXCLUSIVE;

    // Then: Hash code should be consistent across multiple calls
    int hashCode1 = exclusive.hashCode();
    int hashCode2 = exclusive.hashCode();
    assertThat(hashCode1).isEqualTo(hashCode2);
  }

  @Test
  void clinit_enumClassShouldBeLoaded() {
    // When: Accessing the enum class
    Class<WorkflowDirectedGraph.Gateway> gatewayClass = WorkflowDirectedGraph.Gateway.class;

    // Then: The class should be properly loaded and initialized
    assertThat(gatewayClass).isNotNull();
    assertThat(gatewayClass.isEnum()).isTrue();
    assertThat(gatewayClass.getEnumConstants()).hasSize(3);
  }

  @Test
  void clinit_enumConstantsShouldBeAccessibleViaClass() {
    // When: Getting enum constants via the Class object
    WorkflowDirectedGraph.Gateway[] constants = WorkflowDirectedGraph.Gateway.class.getEnumConstants();

    // Then: All three constants should be accessible
    assertThat(constants).hasSize(3);
    assertThat(constants).containsExactly(
        WorkflowDirectedGraph.Gateway.EXCLUSIVE,
        WorkflowDirectedGraph.Gateway.EVENT_BASED,
        WorkflowDirectedGraph.Gateway.PARALLEL
    );
  }

  @Test
  void clinit_valueOfShouldThrowExceptionForInvalidNames() {
    // When/Then: valueOf should properly handle invalid names after initialization
    assertThatCode(() -> WorkflowDirectedGraph.Gateway.valueOf("INVALID"))
        .isInstanceOf(IllegalArgumentException.class);
    assertThatCode(() -> WorkflowDirectedGraph.Gateway.valueOf("exclusive"))
        .isInstanceOf(IllegalArgumentException.class);
  }
}
